"""Regression tests for task 12: legacy-format compatibility.

Legacy records (written by the old version) have no `region` field.
parse() must default it to "" instead of crashing.
"""

import unittest

from records import parse, serialize


class ParseLegacyTest(unittest.TestCase):
    def test_parse_legacy_record_without_region(self):
        # A record written by the OLD version has no "region" key.
        text = '{"name": "alice"}'
        self.assertEqual(parse(text), {"name": "alice", "region": ""})

    def test_parse_new_record_with_region(self):
        text = '{"name": "alice", "region": "us-east"}'
        self.assertEqual(parse(text), {"name": "alice", "region": "us-east"})


class SerializeTest(unittest.TestCase):
    def test_serialize_includes_region(self):
        text = serialize({"name": "bob", "region": "eu"})
        self.assertIn('"region": "eu"', text)

    def test_serialize_empty_region(self):
        text = serialize({"name": "bob", "region": ""})
        self.assertIn('"region": ""', text)


class RoundTripTest(unittest.TestCase):
    def test_roundtrip_with_region(self):
        r = {"name": "carol", "region": "ap-south"}
        self.assertEqual(parse(serialize(r)), r)

    def test_roundtrip_empty_region(self):
        r = {"name": "carol", "region": ""}
        self.assertEqual(parse(serialize(r)), r)


if __name__ == "__main__":
    unittest.main()
